#!/usr/bin/env python3
"""Console arithmetic calculator.

Usage:
    calc.py "2 + 3 * 4"
    echo "2 + 3 * 4" | calc.py

Supported syntax: ``+``, ``-``, ``*``, ``/``, parentheses, unary plus/minus
and arbitrary whitespace.

The result is printed on stdout.  On an error (division by zero, invalid
syntax) a readable message is printed on stderr and the exit status is 2.
"""

from __future__ import annotations

import sys

__all__ = ["CalcError", "evaluate", "format_result", "main"]


class CalcError(Exception):
    """Raised for an invalid expression or a division by zero."""


class _Parser:
    """Recursive descent parser for arithmetic expressions."""

    def __init__(self, text: str) -> None:
        self.text = text
        self.pos = 0

    # -- helpers ---------------------------------------------------------
    def _skip_spaces(self) -> None:
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

    def _peek(self) -> str:
        """Return the next meaningful character ('' at the end of input)."""
        self._skip_spaces()
        if self.pos < len(self.text):
            return self.text[self.pos]
        return ""

    def _error(self, message: str) -> CalcError:
        return CalcError("%s at position %d" % (message, self.pos + 1))

    # -- grammar ---------------------------------------------------------
    def parse(self):
        value = self._expression()
        if self._peek() != "":
            raise self._error("unexpected character %r" % self._peek())
        return value

    def _expression(self):
        """expression := term (('+' | '-') term)*"""
        value = self._term()
        while True:
            ch = self._peek()
            if ch == "+":
                self.pos += 1
                value = value + self._term()
            elif ch == "-":
                self.pos += 1
                value = value - self._term()
            else:
                return value

    def _term(self):
        """term := factor (('*' | '/') factor)*"""
        value = self._factor()
        while True:
            ch = self._peek()
            if ch == "*":
                self.pos += 1
                value = value * self._factor()
            elif ch == "/":
                self.pos += 1
                divisor = self._factor()
                if divisor == 0:
                    raise self._error("division by zero")
                value = self._divide(value, divisor)
            else:
                return value

    @staticmethod
    def _divide(value, divisor):
        """Divide keeping an exact integer result as an ``int``."""
        if isinstance(value, int) and isinstance(divisor, int):
            if value % divisor == 0:
                return value // divisor
            return value / divisor
        result = value / divisor
        if isinstance(result, float) and result.is_integer():
            return int(result)
        return result

    def _factor(self):
        """factor := ('+' | '-') factor | number | '(' expression ')'"""
        ch = self._peek()
        if ch == "":
            raise self._error("unexpected end of expression")
        if ch == "+":
            self.pos += 1
            return self._factor()
        if ch == "-":
            self.pos += 1
            return -self._factor()
        if ch == "(":
            self.pos += 1
            value = self._expression()
            if self._peek() != ")":
                raise self._error("missing closing parenthesis")
            self.pos += 1
            return value
        if ch.isdigit() or ch == ".":
            return self._number()
        raise self._error("unexpected character %r" % ch)

    def _number(self):
        start = self.pos
        while self.pos < len(self.text) and self.text[self.pos].isdigit():
            self.pos += 1
        is_float = False
        if self.pos < len(self.text) and self.text[self.pos] == ".":
            is_float = True
            self.pos += 1
            while self.pos < len(self.text) and self.text[self.pos].isdigit():
                self.pos += 1
        raw = self.text[start:self.pos]
        if raw in ("", "."):
            raise self._error("invalid number")
        if is_float:
            try:
                return float(raw)
            except ValueError:
                raise self._error("invalid number %r" % raw)
        return int(raw)


def evaluate(expression: str):
    """Evaluate an arithmetic expression and return the numeric result."""
    if expression is None:
        raise CalcError("no expression given")
    if not expression.strip():
        raise CalcError("empty expression")
    return _Parser(expression).parse()


def format_result(value) -> str:
    """Render a result the way it should be printed on stdout."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def main(argv=None) -> int:
    """Entry point.  Returns 0 on success and 2 on any error."""
    argv = list(sys.argv if argv is None else argv)
    args = argv[1:]
    if args:
        source = " ".join(args)
    else:
        source = sys.stdin.read()

    try:
        result = evaluate(source)
    except CalcError as exc:
        sys.stderr.write("error: %s\n" % exc)
        return 2
    except RecursionError:
        sys.stderr.write("error: expression is nested too deeply\n")
        return 2

    sys.stdout.write("%s\n" % format_result(result))
    return 0


if __name__ == "__main__":
    sys.exit(main())
